/// The observability tier a record belongs to. ADR-0015 §11.1.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum ObservabilityTier {
    Unspecified = 0,
    /// ALWAYS ON, CANNOT BE DISABLED, NEVER LEAVES THE DEVICE.
    LocalLedger = 1,
    /// Produced on demand; leaves the device ONLY BY EXPLICIT USER ACT, per
    /// artifact. Redacted, pseudonymized, signed, expiring.
    Bundle = 2,
    /// OFF by default, opt-in. Coarse, IDENTIFIER-FREE, k-anonymous counters only.
    Aggregate = 3,
}
impl ObservabilityTier {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            ObservabilityTier::Unspecified => "OBSERVABILITY_TIER_UNSPECIFIED",
            ObservabilityTier::LocalLedger => "OBSERVABILITY_TIER_LOCAL_LEDGER",
            ObservabilityTier::Bundle => "OBSERVABILITY_TIER_BUNDLE",
            ObservabilityTier::Aggregate => "OBSERVABILITY_TIER_AGGREGATE",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "OBSERVABILITY_TIER_UNSPECIFIED" => Some(Self::Unspecified),
            "OBSERVABILITY_TIER_LOCAL_LEDGER" => Some(Self::LocalLedger),
            "OBSERVABILITY_TIER_BUNDLE" => Some(Self::Bundle),
            "OBSERVABILITY_TIER_AGGREGATE" => Some(Self::Aggregate),
            _ => None,
        }
    }
}
